import { chromium } from 'playwright';

const browser = await chromium.launch();
const page = await browser.newPage();
await page.goto('http://localhost:3000/footy/games', { waitUntil: 'networkidle' });
await page.waitForTimeout(1500);
const links = await page.$$eval('a[href^="/footy/game/"]', as => as.map(a => a.getAttribute('href')));
console.log('LINKS', JSON.stringify([...new Set(links)].slice(0, 10)));
await browser.close();

import { chromium } from 'playwright';

const browser = await chromium.launch();
const url = 'http://localhost:3000/footy/game/1';

for (const [name, size] of Object.entries({
  mobile: { width: 390, height: 844 },
  desktop: { width: 1440, height: 900 },
  'desktop-wide': { width: 1920, height: 1080 },
})) {
  const page = await browser.newPage({ viewport: size });
  await page.goto(url, { waitUntil: 'load' });
  await page.waitForTimeout(2500);
  await page.screenshot({ path: `/private/tmp/claude-501/-Volumes-Development-next-www-toastboy/71c139c8-aa0a-4ba6-b492-79558a449dc0/scratchpad/game-${name}.png`, fullPage: true });
  await page.close();
}

await browser.close();
console.log('done');

