1	'use client';
2	
3	import {
4	    AspectRatio,
5	    Image,
6	    type ImageProps,
7	    Skeleton,
8	} from '@mantine/core';
9	import { useCallback, useEffect, useRef, useState } from 'react';
10	
11	export interface Props extends Omit<ImageProps, 'onLoad' | 'onError' | 'src'> {
12	    /** Width / height ratio the space is reserved at, e.g. 1 for square, 3 / 2 for a flag. */
13	    ratio: number;
14	    alt: string;
15	    title?: string;
16	    /** Mantine types this as `any` for Next.js `StaticImageData` compatibility,
17	        but this component always renders a plain `<img>`, so a real API path
18	        is required here. */
19	    src: string;
20	    /** Called once the image has finished loading, or failed to. */
21	    onReady?: () => void;
22	}
23	
24	/**
25	 * Wraps Mantine's Image in a fixed-ratio box so its footprint is reserved
26	 * before the src has loaded, and shows a Skeleton over it until then —
27	 * avoiding the layout shift a bare `Image` causes while its bytes are still
28	 * in flight. `w` sizes the reserved box itself (defaulting to the full width
29	 * of its container); the image inside always fills that box.
30	 */
31	export const ImageWithPlaceholder = ({ ratio, radius, w = '100%', alt, onReady, ...imageProps }: Props) => {
32	    const [loaded, setLoaded] = useState(false);
33	
34	    // If this instance is reused for a different src (rather than remounted),
35	    // reset the skeleton for the new image's own loading lifecycle instead of
36	    // carrying over the previous image's "loaded" status.
37	    const [trackedSrc, setTrackedSrc] = useState(imageProps.src);
38	    if (imageProps.src !== trackedSrc) {
39	        setTrackedSrc(imageProps.src);
40	        setLoaded(false);
41	    }
42	
43	    const onReadyRef = useRef(onReady);
44	    useEffect(() => {
45	        onReadyRef.current = onReady;
46	    }, [onReady]);
47	
48	    // Guards against onReady firing twice for the same src — the mount-time
49	    // `.complete` check below and a subsequent `load`/`error` event can both
50	    // fire for a single image lifecycle.
51	    const readySrcRef = useRef<string | undefined>(undefined);
52	    const handleReady = useCallback(() => {
53	        setLoaded(true);
54	        if (readySrcRef.current !== imageProps.src) {
55	            readySrcRef.current = imageProps.src;
56	            onReadyRef.current?.();
57	        }
58	    }, [imageProps.src]);
59	
60	    // <img onLoad> never fires if the browser has already resolved the image
61	    // (e.g. served from cache) by the time React attaches the listener — a
62	    // well-known race that's especially likely on a fast local dev server.
63	    // A stable ref callback runs exactly once, right as the node mounts, so
64	    // check `.complete` there rather than waiting for an event that may have
65	    // already happened.
66	    const imgRef = useCallback((node: HTMLImageElement | null) => {
67	        if (node?.complete) handleReady();
68	    }, [handleReady]);
69	
70	    return (
71	        <AspectRatio ratio={ratio} w={w} pos="relative">
72	            <Skeleton
73	                visible={!loaded}
74	                radius={radius}
75	                pos="absolute"
76	                inset={0}
77	                aria-hidden="true"
78	            />
79	            <Image
80	                {...imageProps}
81	                ref={imgRef}
82	                alt={alt}
83	                radius={radius}
84	                onLoad={handleReady}
85	                onError={handleReady}
86	                aria-busy={!loaded}
87	                style={{ opacity: loaded ? 1 : 0, transition: 'opacity 150ms ease' }}
88	            />
89	        </AspectRatio>
90	    );
91	};
